"""Shared read-only Order/Invoice browser workspace."""


def order_invoice_html() -> str:
    """Return the browser shell; it uses only the bounded browse GET endpoint."""
    return """<!doctype html><html lang="en"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>APC Core · Order/Invoice</title>
<style>:root{--ink:#24272b;--muted:#68717c;--line:#e5e1db;--cream:#eadbc8;--paper:#fffdfa;--accent:#1d6b57;--tint:#dcefe5}*{box-sizing:border-box}body{margin:0;background:var(--cream);color:var(--ink);font:14px -apple-system,BlinkMacSystemFont,"Segoe UI",sans-serif}.shell{max-width:1120px;margin:auto;padding:28px}.back{color:var(--accent);font-weight:700}.card,.dialog{background:var(--paper);border:1px solid var(--line);border-radius:16px;box-shadow:4px 4px 0 #24272b22}.card{padding:24px}.open{background:var(--accent);color:#fff;border:0;border-radius:10px;padding:11px 14px;font:inherit;font-weight:700;cursor:pointer}.modal{position:fixed;inset:0;z-index:20;display:grid;place-items:center;padding:18px;background:#24272b88}.modal[hidden]{display:none}.dialog{width:min(900px,100%);max-height:90vh;overflow:auto;padding:20px}.toolbar,.tabs,.controls,.actions{display:flex;gap:8px;align-items:center;flex-wrap:wrap}.toolbar{justify-content:space-between}.tab,.secondary{background:#fff;color:var(--accent);border:1px solid var(--line);border-radius:9px;padding:9px 11px;font:inherit;font-weight:700;cursor:pointer}.tab[aria-selected="true"]{background:var(--accent);color:#fff}.controls input{min-width:220px;flex:1;padding:10px;border:1px solid var(--line);border-radius:9px;font:inherit}.authority{margin:14px 0;padding:9px 11px;border-left:4px solid var(--accent);background:var(--tint);font-weight:800;letter-spacing:.04em}.results{margin:0;padding:0;list-style:none}.result{width:100%;margin:7px 0;padding:12px;text-align:left;background:#fff;border:1px solid var(--line);border-radius:10px;cursor:pointer}.result[aria-selected="true"]{background:var(--tint);outline:3px solid #9acbb9}.meta{display:block;color:var(--muted);font-size:12px;margin-top:4px}.detail{min-height:38px;color:var(--muted)}button:focus-visible,input:focus-visible{outline:3px solid var(--accent);outline-offset:2px}@media(max-width:620px){.shell{padding:16px}.dialog{padding:15px}.controls input{min-width:100%}}</style>
<body><main id="order-invoice-workspace" class="shell"><a class="back" href="../">Main menu</a><section class="card"><p>Read-only source browsing and local draft review. Records remain separate; this workspace does not create a relationship between them.</p><button id="open-order-invoice" class="open" type="button">Open Order/Invoice</button></section></main>
<section id="order-invoice-modal" class="modal" role="dialog" aria-modal="true" aria-labelledby="order-invoice-title" hidden><div class="dialog"><div class="toolbar"><h1 id="order-invoice-title">Order/Invoice</h1><button id="close-order-invoice" class="secondary" type="button">Close</button></div><div id="order-invoice-tabs" class="tabs" role="tablist" aria-label="Order and invoice record filters"><button class="tab" type="button" role="tab" aria-selected="true" data-type="source_order">Source Orders</button><button class="tab" type="button" role="tab" aria-selected="false" data-type="source_invoice">Source Invoices</button><button class="tab" type="button" role="tab" aria-selected="false" data-type="core_draft">Core Drafts</button></div><p id="order-invoice-authority" class="authority">SOURCE ORDER · READ-ONLY</p><div class="controls"><input id="order-invoice-query" aria-label="Search selected records" autocomplete="off"><button id="browse-order-invoice" class="open" type="button">Browse</button></div><p id="order-invoice-status" class="meta">Enter a search value to browse the selected records.</p><ul id="order-invoice-results" class="results" aria-label="Browse results"></ul><div class="actions"><button id="open-order-invoice-result" class="secondary" type="button">Open selected</button></div><p id="order-invoice-detail" class="detail" aria-live="polite"></p></div></section>
<script>(()=>{const $=selector=>document.querySelector(selector),modal=$('#order-invoice-modal'),openButton=$('#open-order-invoice'),closeButton=$('#close-order-invoice'),tabs=[...document.querySelectorAll('#order-invoice-tabs [role="tab"]')],query=$('#order-invoice-query'),authority=$('#order-invoice-authority'),status=$('#order-invoice-status'),results=$('#order-invoice-results'),detail=$('#order-invoice-detail');let invoker=openButton,activeIndex=0,selected=null;const labels={source_order:'SOURCE ORDER · READ-ONLY',source_invoice:'SOURCE INVOICE · READ-ONLY',core_draft:'CORE DRAFT · LOCAL'};function selectedType(){return tabs[activeIndex].dataset.type}function setFilter(index){activeIndex=(index+tabs.length)%tabs.length;tabs.forEach((tab,tabIndex)=>tab.setAttribute('aria-selected',String(tabIndex===activeIndex)));authority.textContent=labels[selectedType()];selected=null;results.replaceChildren();detail.textContent='';status.textContent='Enter a search value to browse the selected records.'}function close(){modal.hidden=true;invoker.focus()}function focusable(){return [...modal.querySelectorAll('button:not([disabled]),input:not([disabled])')].filter(node=>!node.hidden)}function trap(event){const nodes=focusable();if(!nodes.length)return;const first=nodes[0],last=nodes[nodes.length-1];if(event.shiftKey&&document.activeElement===first){event.preventDefault();last.focus()}else if(!event.shiftKey&&document.activeElement===last){event.preventDefault();first.focus()}}function open(){invoker=document.activeElement instanceof HTMLElement?document.activeElement:openButton;modal.hidden=false;setFilter(activeIndex);tabs[activeIndex].focus()}function textFor(record){if(record.record_type==='source_order')return [record.order_id,record.order_date,record.customer_id].filter(Boolean).join(' · ');if(record.record_type==='source_invoice')return [record.source_invoice_number,record.invoice_date,record.customer_id,record.customer_name].filter(Boolean).join(' · ');return [record.draft_id,record.status,record.created_by,record.created_at].filter(Boolean).join(' · ')}function render(payload){results.replaceChildren();selected=null;status.textContent=String(payload.total||0)+' result(s)';for(const record of payload.results||[]){const row=document.createElement('li'),button=document.createElement('button'),meta=document.createElement('span');button.type='button';button.className='result';button.textContent=textFor(record);button.setAttribute('aria-selected','false');meta.className='meta';meta.textContent=labels[record.record_type]||'';button.append(meta);button.addEventListener('click',()=>{[...results.querySelectorAll('.result')].forEach(node=>node.setAttribute('aria-selected','false'));button.setAttribute('aria-selected','true');selected=record});row.append(button);results.append(row)}}async function browse(){const value=query.value.trim();if(!value){status.textContent='Enter a search value to browse the selected records.';results.replaceChildren();return}const params=new URLSearchParams({type:selectedType(),query:value,limit:'50',offset:'0'});status.textContent='Browsing…';try{const response=await fetch('api/browse?type='+encodeURIComponent(params.get('type'))+'&query='+encodeURIComponent(params.get('query'))+'&limit='+params.get('limit')+'&offset='+params.get('offset'),{credentials:'same-origin',cache:'no-store'});if(!response.ok)throw new Error();render(await response.json())}catch(_){results.replaceChildren();status.textContent='Browse unavailable for the selected records.'}}function openSelected(){if(!selected){detail.textContent='Select a result first.';return}detail.textContent='Opened '+(selected.record_id||'record')+' for read-only review.'}openButton.addEventListener('click',open);closeButton.addEventListener('click',close);$('#browse-order-invoice').addEventListener('click',browse);$('#open-order-invoice-result').addEventListener('click',openSelected);query.addEventListener('keydown',event=>{if(event.key==='Enter'){event.preventDefault();browse()}});tabs.forEach((tab,index)=>tab.addEventListener('click',()=>setFilter(index)));modal.addEventListener('keydown',event=>{if(event.key==='Escape'){event.preventDefault();close();return}if(event.key==='Tab'){trap(event);return}if(event.key==='ArrowRight'){event.preventDefault();setFilter(activeIndex+1);tabs[activeIndex].focus();return}if(event.key==='ArrowLeft'){event.preventDefault();setFilter(activeIndex-1);tabs[activeIndex].focus();return}if(event.key==='Enter'&&event.target.classList.contains('result')){event.preventDefault();event.target.click();openSelected()}})})();</script></body></html>"""
